export enum SessionState {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    SessionActive = "active",
    SessionExpiring = "expiring",
    SessionRefreshable = "refreshable",
    SessionExpired = "expired",
    SessionSignedOut = "signed-out",
    SessionSigningIn = "signing-in",
    SessionError = "error",
};

export interface SessionStatus {
    "portal": string;
    "state": SessionState;

    /**
     * ACCESS TOKEN expiry (~1 h, renews itself). Details only, never the main countdown
     */
    "expiresAt"?: string;

    /**
     * when this app last wrote/refreshed the access token (record TokenIssuedAt)
     */
    "issuedAt"?: string;

    /**
     * this app did the sign-in that produced the cached token (clientId lineage matches)
     */
    "sessionKnown": boolean;

    /**
     * interactive sign-in time; only when SessionKnown
     */
    "loginAt"?: string;

    /**
     * LoginAt + SessionMinutes (estimate); only when SessionKnown
     */
    "sessionEndsAt"?: string;

    /**
     * per-portal setting, default 480 (8 h), range 15..129600
     */
    "sessionMinutes": number;

    /**
     * SessionKnown, now > SessionEndsAt, token still valid or renewable
     */
    "sessionOverrun": boolean;

    /**
     * 0..100 = session left / SessionMinutes; 0 when !SessionKnown or SessionOverrun (UI hides the bar)
     */
    "progressPct": number;
    "canRefresh": boolean;
    "refreshing": boolean;

    /**
     * set when State == error, or the last refresh hit a network error
     */
    "error"?: AppError | null;
}

